import { useEffect } from 'react';
import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import type { Color, PieceType } from '@/types/remorse';

// SVGs are generated by scripts/remorse-pieces.mjs; ids must match its SETS
export const PIECE_SETS = [
  { id: 'mourners', name: 'Mourners' },
  { id: 'chunky', name: 'Chunky' },
  { id: 'staunton', name: 'Stout Staunton' },
  { id: 'monuments', name: 'Monuments' },
  { id: 'pebble', name: 'Pebble' },
] as const;

export type PieceSetId = (typeof PIECE_SETS)[number]['id'];

export const BOARD_SRC = '/images/remorse/board.svg';

export const pieceSrc = (set: PieceSetId, color: Color, type: PieceType) =>
  `/images/remorse/pieces/${set}/${color}${type}.svg`;

const isPieceSet = (id: unknown): id is PieceSetId =>
  PIECE_SETS.some((set) => set.id === id);

interface PieceSetStore {
  pieceSet: PieceSetId;
  setPieceSet: (pieceSet: PieceSetId) => void;
}

// Saved per browser. Hydration is manual so the server render and the first
// client render agree on the default set.
const usePieceSetStore = create<PieceSetStore>()(
  persist(
    (set) => ({
      pieceSet: 'mourners',
      setPieceSet: (pieceSet) => set({ pieceSet }),
    }),
    {
      name: 'remorse-piece-set',
      skipHydration: true,
      merge: (persisted, current) => {
        const saved =
          persisted && typeof persisted === 'object' && 'pieceSet' in persisted
            ? persisted.pieceSet
            : undefined;
        return isPieceSet(saved) ? { ...current, pieceSet: saved } : current;
      },
    },
  ),
);

export const usePieceSet = () => {
  useEffect(() => {
    usePieceSetStore.persist.rehydrate();
  }, []);
  return usePieceSetStore();
};
